import { useEffect, useRef, useState } from "react";

/**
 * <ECellFanout />
 * "You" -> E-Cell hub -> 5 pillars. Lines draw left→right, each card pops in
 * as its line arrives, then the sequence loops.
 *
 * Zero dependencies (React only). Styles are scoped under .ecf-*.
 * `hubLogoSrc` = centre hub logo (handshake icon); `logoSrc` = small logo next to the title.
 * `brandLogoSrc` = full brand logo top-left; pass "" to fall back to logoSrc + title text.
 */

const I = (children) => (
  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round">
    {children}
  </svg>
);

const ICONS = {
  user: I(<><path d="M19 21v-2a4 4 0 0 0-4-4H9a4 4 0 0 0-4 4v2" /><circle cx="12" cy="7" r="4" /></>),
  users: I(<><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2" /><circle cx="9" cy="7" r="4" /><path d="M22 21v-2a4 4 0 0 0-3-3.87" /><path d="M16 3.13a4 4 0 0 1 0 7.75" /></>),
  bulb: I(<><path d="M15 14c.2-1 .7-1.7 1.5-2.5 1-.9 1.5-2.2 1.5-3.5A6 6 0 0 0 6 8c0 1 .2 2.2 1.5 3.5.7.7 1.3 1.5 1.5 2.5" /><path d="M9 18h6" /><path d="M10 22h4" /></>),
  book: I(<><path d="M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z" /><path d="M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z" /></>),
  handshake: I(<><path d="m11 17 2 2a1 1 0 1 0 3-3" /><path d="m14 14 2.5 2.5a1 1 0 1 0 3-3l-3.88-3.88a3 3 0 0 0-4.24 0l-.88.88a1 1 0 1 1-3-3l2.81-2.81a5.79 5.79 0 0 1 7.06-.87l.47.28a2 2 0 0 0 1.42.25L21 4" /><path d="m21 3 1 11h-2" /><path d="M3 3 2 14l6.5 6.5a1 1 0 1 0 3-3" /><path d="M3 4h8" /></>),
  rocket: I(<><path d="M4.5 16.5c-1.5 1.26-2 5-2 5s3.74-.5 5-2c.71-.84.7-2.13-.09-2.91a2.18 2.18 0 0 0-2.91-.09z" /><path d="m12 15-3-3a22 22 0 0 1 2-3.95A12.88 12.88 0 0 1 22 2c0 2.72-.78 7.5-6 11a22.35 22.35 0 0 1-4 2z" /><path d="M9 12H4s.55-3.03 2-4c1.62-1.08 5 0 5 0" /><path d="M12 15v5s3.03-.55 4-2c1.08-1.62 0-5 0-5" /></>),
};

const DEFAULT_ITEMS = [
  { icon: "users", title: "Community", text: "Connecting like-minded students, engineers, and creators." },
  { icon: "bulb", title: "Ideation", text: "Validating raw concepts and turning them into real-world business models." },
  { icon: "book", title: "Workshops", text: "Direct learning through hands-on bootcamps, speaker sessions, and tech masterclasses." },
  { icon: "handshake", title: "Mentorship", text: "Access to regional founders, alumni, and incubation managers." },
  { icon: "rocket", title: "Incubation", text: "A clear path to building minimum viable products (MVPs) in cooperation with campus infrastructure." },
];

/* handshake logo, embedded so no file path is needed */
const HANDSHAKE_LOGO = "data:image/png;base64,";

/* full E-Cell JCER brand logo (handshake mark + wordmark), embedded */
const BRAND_LOGO = "data:image/png;base64,";

/* ---- stage geometry (design space 1240 x 520, scaled to fit) ---- */
const W = 1240, H = 520;
const HUB_Y = 262, SPINE = 640, R = 12;
const CARD_X = 790, CARD_W = 420, CARD_H = 80, GAP = 92;

function Logo({ src, size, rounded = true }) {
  const [failed, setFailed] = useState(!src);
  useEffect(() => setFailed(!src), [src]);
  if (failed) {
    return (
      <svg width={size} height={size} viewBox="0 0 48 48" aria-label="E-Cell">
        <defs>
          <linearGradient id="ecf-g" x1="0" y1="0" x2="1" y2="1">
            <stop offset="0" stopColor="#60a5fa" /><stop offset="1" stopColor="#1d4ed8" />
          </linearGradient>
        </defs>
        <circle cx="24" cy="24" r="22" fill="url(#ecf-g)" />
        <text x="24" y="31" textAnchor="middle" fontSize="22" fontWeight="700" fill="#fff" fontFamily="inherit">E</text>
      </svg>
    );
  }
  return (
    <img src={src} alt="E-Cell logo" width={size} height={size}
      style={{ objectFit: "contain", borderRadius: rounded ? "50%" : 0 }} onError={() => setFailed(true)} />
  );
}

export default function ECellFanout({
  logoSrc = "",
  brandLogoSrc = BRAND_LOGO, // full brand logo shown top-left (replaces small logo + title text)
  hubLogoSrc = HANDSHAKE_LOGO, // logo shown in the centre hub

  youLabel = "You",
  title = "E-Cell",
  items = DEFAULT_ITEMS,
}) {
  const wrapRef = useRef(null);
  const [scale, setScale] = useState(1);
  const [step, setStep] = useState(0);
  const N = items.length;
  const MAX = N + 2; // 1 = "You" line, 2 = hub, 3..N+2 = each pillar

  // fit stage to container width
  useEffect(() => {
    const el = wrapRef.current;
    if (!el) return;
    const fit = () => setScale(Math.min(1, el.clientWidth / W));
    fit();
    const ro = new ResizeObserver(fit);
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  // animation timeline
  useEffect(() => {
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      setStep(MAX);
      return;
    }
    let timer, dead = false;
    const later = (fn, ms) => { timer = setTimeout(() => !dead && fn(), ms); };
    const run = () => {
      setStep(0);
      let s = 0;
      const tick = () => {
        s += 1;
        setStep(s);
        if (s < MAX) later(tick, s === 1 ? 650 : 380);
        else later(() => { setStep(0); later(run, 700); }, 4200);
      };
      later(tick, 500);
    };
    run();
    return () => { dead = true; clearTimeout(timer); };
  }, [MAX]);

  const cy = (i) => HUB_Y + (i - (N - 1) / 2) * GAP;

  const pathFor = (y) => {
    const dy = y - HUB_Y;
    if (Math.abs(dy) < 1) return `M499 ${HUB_Y}H${CARD_X - 10}`;
    const s = Math.sign(dy);
    return `M499 ${HUB_Y}H${SPINE - R}Q${SPINE} ${HUB_Y} ${SPINE} ${HUB_Y + s * R}V${y - s * R}Q${SPINE} ${y} ${SPINE + R} ${y}H${CARD_X - 10}`;
  };

  return (
    <div className="ecf-root">
      {/* Seamless Ambient Transition Glows */}
      <div className="absolute top-0 left-1/2 -translate-x-1/2 w-3/4 h-48 bg-gradient-to-b from-transparent via-[#072a66]/20 to-transparent blur-3xl pointer-events-none" />
      <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[700px] h-[350px] bg-[#3086f8]/10 blur-[100px] pointer-events-none" />
      <style>{CSS}</style>
      <div ref={wrapRef} className="ecf-wrap" style={{ height: H * scale }}>
        <div className="ecf-stage" style={{ transform: `scale(${scale})` }}>
          <div className="ecf-panel" />
          <div className="ecf-title">
            {brandLogoSrc ? (
              <img src={brandLogoSrc} alt="E-Cell JCER" className="ecf-brand" />
            ) : (
              <>
                <Logo src={logoSrc} size={26} />
                {title}
              </>
            )}
          </div>

          <svg className="ecf-lines" viewBox={`0 0 ${W} ${H}`}>
            {/* You -> hub */}
            <path className={`ecf-ln ${step >= 1 ? "on" : ""}`} d={`M222 ${HUB_Y}H388`} pathLength="1" />
            <polygon className={`ecf-ar ${step >= 1 ? "on" : ""}`} points={`388,${HUB_Y - 4} 398,${HUB_Y} 388,${HUB_Y + 4}`} />
            {/* hub -> pillars */}
            {items.map((_, i) => {
              const y = cy(i), on = step >= i + 3;
              return (
                <g key={i}>
                  <path className={`ecf-ln ${on ? "on" : ""}`} d={pathFor(y)} pathLength="1" />
                  <polygon className={`ecf-ar ${on ? "on" : ""}`} points={`${CARD_X - 10},${y - 4} ${CARD_X},${y} ${CARD_X - 10},${y + 4}`} />
                </g>
              );
            })}
          </svg>

          <div className="ecf-you" style={{ top: HUB_Y - 38 }}>
            <span className="ecf-ic">{ICONS.user}</span>
            {youLabel}
          </div>

          <div className={`ecf-hub ${step >= 2 ? "on" : ""}`}>
            <Logo src={hubLogoSrc || logoSrc} size={62} rounded={false} />
          </div>

          {items.map((it, i) => (
            <div key={it.title} className={`ecf-card ${step >= i + 3 ? "on" : ""}`}
              style={{ top: cy(i) - CARD_H / 2, left: CARD_X, width: CARD_W, height: CARD_H }}>
              <span className="ecf-tile">{ICONS[it.icon]}</span>
              <div className="ecf-txt">
                <div className="ecf-h">{it.title}</div>
                <div className="ecf-p">{it.text}</div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

const CSS = `
.ecf-root{width:100%;padding:48px 16px;color:#fff;font-family:inherit;
  background:transparent;position:relative}
.ecf-wrap{width:100%;max-width:${W}px;margin:0 auto;position:relative}
.ecf-stage{position:absolute;left:0;top:0;width:${W}px;height:${H}px;transform-origin:0 0}
.ecf-panel{position:absolute;left:306px;top:18px;width:935px;height:485px;border-radius:28px;
  background:linear-gradient(180deg,rgba(13,25,52,.55),rgba(9,22,52,.35));
  border:1px solid rgba(59,130,246,.22);box-shadow:0 0 60px rgba(37,99,235,.12) inset,0 10px 40px rgba(0,0,0,.4);
  background-image:radial-gradient(rgba(96,165,250,.16) 1px,transparent 1px);background-size:20px 20px}
.ecf-title{position:absolute;left:336px;top:30px;display:flex;align-items:center;gap:12px;font-size:22px;font-weight:600;letter-spacing:.2px}
.ecf-brand{height:84px;width:auto;display:block;object-fit:contain}
.ecf-lines{position:absolute;left:0;top:0;width:${W}px;height:${H}px;overflow:visible}
.ecf-ln{fill:none;stroke:#3b82f6;stroke-opacity:.75;stroke-width:2;stroke-linecap:round;stroke-dasharray:1;stroke-dashoffset:1;
  filter:drop-shadow(0 0 4px rgba(59,130,246,.55))}
.ecf-ln.on{stroke-dashoffset:0;transition:stroke-dashoffset .52s cubic-bezier(.4,0,.2,1)}
.ecf-ar{fill:#60a5fa;opacity:0}
.ecf-ar.on{opacity:1;transition:opacity .2s ease .5s}
.ecf-you{position:absolute;left:0;width:222px;height:76px;border-radius:16px;display:flex;align-items:center;gap:14px;padding:0 22px;
  font-size:22px;font-weight:600;background:linear-gradient(180deg,#101a31,#0b1428);border:1px solid rgba(59,130,246,.28);
  box-shadow:0 6px 24px rgba(0,0,0,.45)}
.ecf-ic{width:24px;height:24px;color:#60a5fa;display:block}
.ecf-ic svg,.ecf-tile svg{width:100%;height:100%;display:block}
.ecf-hub{position:absolute;left:401px;top:${HUB_Y - 49}px;width:98px;height:98px;border-radius:50%;display:flex;align-items:center;justify-content:center;
  background:radial-gradient(circle at 30% 25%,#13244a,#0a1530);border:1px solid rgba(96,165,250,.4);
  box-shadow:0 0 0 6px rgba(37,99,235,.08),0 0 40px rgba(37,99,235,.35);transition:transform .35s cubic-bezier(.3,1.6,.5,1),box-shadow .35s}
.ecf-hub.on{transform:scale(1.08);box-shadow:0 0 0 8px rgba(37,99,235,.14),0 0 56px rgba(59,130,246,.55)}
.ecf-card{position:absolute;display:flex;align-items:center;gap:16px;padding:0 18px;border-radius:16px;
  background:linear-gradient(180deg,rgba(18,30,58,.95),rgba(10,20,42,.95));border:1px solid rgba(59,130,246,.25);
  box-shadow:0 6px 24px rgba(0,0,0,.45);opacity:0;transform:translateX(-12px) scale(.96)}
.ecf-card.on{opacity:1;transform:none;transition:opacity .35s ease .5s,transform .45s cubic-bezier(.3,1.4,.5,1) .5s}
.ecf-tile{flex:none;width:46px;height:46px;border-radius:13px;padding:11px;color:#60a5fa;
  background:#0f2447;border:1px solid rgba(59,130,246,.35)}
.ecf-h{font-size:18px;font-weight:600;line-height:1.2}
.ecf-p{margin-top:4px;font-size:13px;line-height:1.4;color:#9fb0cc}
@media (prefers-reduced-motion:reduce){.ecf-ln,.ecf-card,.ecf-ar{transition:none!important}}
`;
